SELECT $j$le-hoi-hoa-xuan-sa-dec-2027$j$, 'article', 'su-kien', $j$Phường Sa Đéc chuẩn bị Lễ hội hoa xuân và chương trình nghệ thuật giao thừa 2027$j$,
  $j$Lễ hội hoa xuân Sa Đéc 2027 chủ đề “Xuân về đất nở ngàn hoa” dự kiến diễn ra từ 3 đến 10/2/2027 với đường hoa xuân dài 300 m, đại cảnh hoa hồng và linh vật dê; chương trình giao thừa “Xuân nối những mùa hoa” tối 5/2/2027 tại Quảng trường Sa Đéc.$j$,
  $j$[{"type": "p", "text": "Chiều 7/10/2026, Thường trực Đảng ủy phường Sa Đéc làm việc với đơn vị tư vấn về công tác chuẩn bị **Lễ hội hoa xuân Sa Đéc 2027** và **Chương trình nghệ thuật Lễ hội giao thừa xuân Đinh Mùi 2027**."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/Hoa_t%E1%BA%A1i_Sa_%C4%90%C3%A9c_%28cropped%29.jpg/1280px-Hoa_t%E1%BA%A1i_Sa_%C4%90%C3%A9c_%28cropped%29.jpg", "caption": "Những luống hoa tại làng hoa Sa Đéc (ảnh: Bùi Thụy Đào Nguyên, CC BY-SA 3.0, Wikimedia Commons)"}, {"type": "h2", "text": "🌸 Lễ hội hoa xuân “Xuân về đất nở ngàn hoa”"}, {"type": "p", "text": "Theo phương án đề xuất, Lễ hội hoa xuân Sa Đéc 2027 với chủ đề “Xuân về đất nở ngàn hoa” dự kiến diễn ra **từ ngày 3 đến 10/2/2027**, nổi bật với:"}, {"type": "list", "ordered": false, "items": ["Đường hoa xuân dài **300 m**.", "Đại cảnh hoa hồng.", "Biểu tượng linh vật dê năm 2027."]}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b9/Ch%E1%BB%A3_hoa_C%C3%B4ng_vi%C3%AAn_Fidel%2C_T%E1%BA%BFt_2022_%28hoa_c%C3%BAc_v%C3%A0ng%2C_b%E1%BA%A1t_ng%C3%A0n%29_%285%29.jpg/1280px-Ch%E1%BB%A3_hoa_C%C3%B4ng_vi%C3%AAn_Fidel%2C_T%E1%BA%BFt_2022_%28hoa_c%C3%BAc_v%C3%A0ng%2C_b%E1%BA%A1t_ng%C3%A0n%29_%285%29.jpg", "caption": "Cúc vàng rực rỡ ngày Tết (ảnh minh họa: Phương Huy, CC BY-SA 4.0, Wikimedia Commons)"}, {"type": "h2", "text": "🎆 Chương trình nghệ thuật giao thừa “Xuân nối những mùa hoa”"}, {"type": "p", "text": "Chương trình nghệ thuật giao thừa với chủ đề “Xuân nối những mùa hoa” dự kiến diễn ra **từ 20 đến 22 giờ ngày 5/2/2027** tại **Quảng trường Sa Đéc**, được truyền hình trực tiếp trên sóng truyền hình Đồng Tháp và các nền tảng số."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c0/Hoa_ng%C3%A0y_T%E1%BA%BFt.jpg/1280px-Hoa_ng%C3%A0y_T%E1%BA%BFt.jpg", "caption": "Sắc hoa ngày Tết (ảnh minh họa, phạm vi công cộng, Wikimedia Commons)"}, {"type": "p", "text": "Tại buổi làm việc, lãnh đạo phường đề nghị đơn vị tư vấn tiếp tục hoàn chỉnh kế hoạch, hồ sơ và các phương án tổ chức, góp phần chuẩn bị chu đáo cho chuỗi hoạt động văn hóa, du lịch và xúc tiến đầu tư của Sa Đéc trong dịp Tết Đinh Mùi 2027."}, {"type": "image", "file": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/2a/Mai_v%C3%A0ng.jpg/1280px-Mai_v%C3%A0ng.jpg", "caption": "Mai vàng chưng Tết (ảnh minh họa, phạm vi công cộng, Wikimedia Commons)"}, {"type": "note", "title": "Lưu ý", "text": "Thời gian, địa điểm là phương án dự kiến, có thể thay đổi theo thông báo chính thức của phường Sa Đéc."}]$j$::jsonb, $j$https://upload.wikimedia.org/wikipedia/commons/thumb/b/b9/Ch%E1%BB%A3_hoa_C%C3%B4ng_vi%C3%AAn_Fidel%2C_T%E1%BA%BFt_2022_%28hoa_c%C3%BAc_v%C3%A0ng%2C_b%E1%BA%A1t_ng%C3%A0n%29_%285%29.jpg/1280px-Ch%E1%BB%A3_hoa_C%C3%B4ng_vi%C3%AAn_Fidel%2C_T%E1%BA%BFt_2022_%28hoa_c%C3%BAc_v%C3%A0ng%2C_b%E1%BA%A1t_ng%C3%A0n%29_%285%29.jpg$j$, 2, 'Cây Cảnh Miền Tây',
